+const isPlainObject = value => {
+  if (value === null || typeof value !== 'object') return false;
+  const prototype = Object.getPrototypeOf(value);
+  return prototype === Object.prototype || prototype === null;
+};
+
+const isNonNegativeInteger = value => Number.isInteger(value) && value >= 0;
+
+export function calculateReorderRecommendation(input) {
+  if (
+    !isPlainObject(input) ||
+    requiredFields.some(field => !isNonNegativeInteger(input[field]))
+  ) {
+    throw new TypeError('invalid stock policy');
+  }
+
+  const available = Math.max(0, input.onHand - input.reserved);
+  const reorder =
+    available >= input.reorderPoint
+      ? 0
+      : Math.max(0, input.targetStock - available);
+
+  return { available, reorder, needsReorder: reorder > 0 };
